(59642, 1504, 46, '<td valign="top">nice job rocky</td>', 'nice job rocky', '2002-05-13 01:21:00.000000', NULL, 1),
(59643, 1504, 772, '<td valign="top">I love the perspective of this shot... It appears to be a tad over exposed... possibly some brightness control and maybe a little added contrast would have been nice... the squirrell is a tad blurry but the sense of motion there is good :)</td>', 'I love the perspective of this shot... It appears to be a tad over exposed... possibly some brightness control and maybe a little added contrast would have been nice... the squirrell is a tad blurry but the sense of motion there is good :)', '2002-05-13 16:08:00.000000', NULL, 1),
(59644, 1504, 54, '<td valign="top">If only it weren''t blurry. Next time offer him peanuts and he might stay still longer.</td>', 'If only it weren''t blurry. Next time offer him peanuts and he might stay still longer.', '2002-05-13 16:11:00.000000', NULL, 1),
(59645, 1504, 1024, '<td valign="top">Nice concept, but the focus is too soft for my taste.</td>', 'Nice concept, but the focus is too soft for my taste.', '2002-05-13 08:20:00.000000', NULL, 1),
(59646, 1504, 1, '<td valign="top">Focus seems off, faster shutter would reduce blur on the squirrel.</td>', 'Focus seems off, faster shutter would reduce blur on the squirrel.', '2002-05-13 08:47:00.000000', NULL, 1),
(59647, 1504, 1379, '<td valign="top">So fluffy and cute!</td>', 'So fluffy and cute!', '2002-05-13 09:08:00.000000', NULL, 1),
(59648, 1504, 1378, '<td valign="top">Could be a nice photo, but the focus needs to be better.</td>', 'Could be a nice photo, but the focus needs to be better.', '2002-05-13 10:13:00.000000', NULL, 1),
(59649, 1504, 327, '<td valign="top">Your deck makes it look like a real ceiling. Cute and as much on the topic as can be. Buggers don''t hold still do they? Nice job.</td>', 'Your deck makes it look like a real ceiling. Cute and as much on the topic as can be. Buggers don''t hold still do they? Nice job.', '2002-05-13 15:30:00.000000', NULL, 1),
