(59651, 1504, 472, '<td valign="top">yeeek its going to drop into my huge hairdo!</td>', 'yeeek its going to drop into my huge hairdo!', '2002-05-13 18:25:00.000000', NULL, 1),
(59652, 1504, 1457, '<td valign="top">hey, you little monkey squirrel, whay do you not come to me!</td>', 'hey, you little monkey squirrel, whay do you not come to me!', '2002-05-13 19:21:00.000000', NULL, 1),
(59653, 1504, 686, '<td valign="top">The squirrel is a little bit too blurry.</td>', 'The squirrel is a little bit too blurry.', '2002-05-13 20:58:00.000000', NULL, 1),
(59654, 1504, 862, '<td valign="top">I like the idea and title, but it looks like the squirrel moved as you took the photo.  Try a faster shutter speed.</td>', 'I like the idea and title, but it looks like the squirrel moved as you took the photo.  Try a faster shutter speed.', '2002-05-14 10:31:00.000000', NULL, 1),
(59655, 1504, 1005, '<td valign="top">Try faster exposure for wild animal shots, but I like it.  Photo 5 Creativity 6 Upsidedown 6 total 6</td>', 'Try faster exposure for wild animal shots, but I like it.  Photo 5 Creativity 6 Upsidedown 6 total 6', '2002-05-14 14:24:00.000000', NULL, 1),
(59656, 1504, 107, '<td valign="top">As hard as they are to catch, I wouldn''t have minded seeing mr.spider squirrel more in focus.</td>', 'As hard as they are to catch, I wouldn''t have minded seeing mr.spider squirrel more in focus.', '2002-05-15 09:20:00.000000', NULL, 1),
(59657, 1504, 1135, '<td valign="top">Too bad it''s a bit blurred. Other wise it''s a great shot.</td>', 'Too bad it''s a bit blurred. Other wise it''s a great shot.', '2002-05-16 01:30:00.000000', NULL, 1),
(59658, 1504, 259, '<td valign="top">the whole photo looks a bit blurry</td>', 'the whole photo looks a bit blurry', '2002-05-16 23:33:00.000000', NULL, 1),
(59659, 1504, 1078, '<td valign="top">Clever.  A faster shutter speed would have let you freeze the squirrel''s motion.  The colors here also seem a little flat.  It may be that this is entirely true to the location, but I think a littel tweak in a PS like program, would help make some of the color pop.  (Or, if not, maybe think black and white instead...)</td>', 'Clever.  A faster shutter speed would have let you freeze the squirrel''s motion.  The colors here also seem a little flat.  It may be that this is entirely true to the location, but I think a littel tweak in a PS like program, would help make some of the color pop.  (Or, if not, maybe think black and white instead...)', '2002-05-19 17:13:00.000000', NULL, 1),
(59660, 1504, 1042, '<td valign="top">lol..love the title..great</td>', 'lol..love the title..great', '2002-05-19 20:51:00.000000', NULL, 1),
(59661, 1504, 570, '<td valign="top">woohoo #88!!</td>', 'woohoo #88!!', '2002-05-20 11:06:00.000000', NULL, 0),
(59662, 1509, 1344, '<td valign="top">Terrific!  Can''t find anything to complain about on this one :)  Very boring photo when right-side up, but perfect for this challenge!</td>', 'Terrific!  Can''t find anything to complain about on this one :)  Very boring photo when right-side up, but perfect for this challenge!', '2002-05-13 01:53:00.000000', NULL, 1),
(59663, 1509, 1037, '<td valign="top">Wow! Awesome photograph!!! The coins are a great effect, those trees are wonderful, the curve of the ''horizon'' lifts the composition really beautifully, and I love those streetlights. Black and white brings out the trees and the ''sky'' gorgeously. 10 from me, definitely! (Sigh... I need to think up more interesting adjectives/adverbs).</td>', 'Wow! Awesome photograph!!! The coins are a great effect, those trees are wonderful, the curve of the ''horizon'' lifts the composition really beautifully, and I love those streetlights. Black and white brings out the trees and the ''sky'' gorgeously. 10 from me, definitely! (Sigh... I need to think up more interesting adjectives/adverbs).', '2002-05-13 03:21:00.000000', NULL, 1),
(59664, 1509, 1360, '<td valign="top">It''s a cliche.  But it''s a wonderfully done one.</td>', 'It''s a cliche.  But it''s a wonderfully done one.', '2002-05-13 03:49:00.000000', NULL, 1),
(59665, 1509, 1485, '<td valign="top">Super cool!!!</td>', 'Super cool!!!', '2002-05-13 06:47:00.000000', NULL, 1),
(59666, 1509, 87, '<td valign="top">awesome. at first i thought it was edited in photoshop to create the grid in the sky and then i realized it was tiles and coins, rad =)</td>', 'awesome. at first i thought it was edited in photoshop to create the grid in the sky and then i realized it was tiles and coins, rad =)', '2002-05-13 07:05:00.000000', NULL, 1),
