(59680, 1509, 1599, '<td valign="top">that was not taken this week</td>', 'that was not taken this week', '2002-05-13 17:42:00.000000', NULL, 1),
(59681, 1509, 472, '<td valign="top">woah!  twilight zone reality!!  I freakin'' LOVE this!!  this is soooo well seen, and works so well as a b&amp;w.</td>', 'woah!  twilight zone reality!!  I freakin'' LOVE this!!  this is soooo well seen, and works so well as a b&w.', '2002-05-13 18:20:00.000000', NULL, 1),
(59682, 1509, 772, '<td valign="top">I won''t say much more than WOW about this photo.  I think I see what is going on here.. an inverted camera over a man-made pool with a tile base?  A wishing pool?  The black and white and the bare trees really give this photo an element of ''coldness''... maybe the well wishers are wishing for summer time :) = 10</td>', 'I won''t say much more than WOW about this photo.  I think I see what is going on here.. an inverted camera over a man-made pool with a tile base?  A wishing pool?  The black and white and the bare trees really give this photo an element of ''coldness''... maybe the well wishers are wishing for summer time :) = 10', '2002-05-13 18:26:00.000000', NULL, 1),
(59683, 1509, 1446, '<td valign="top">I really like the coins in the bottom of the fountain.  You must be someplace really cold.  Even in Michigan we have leaves on the trees at this point!  Seriously, nice job.<br/></td>', 'I really like the coins in the bottom of the fountain.  You must be someplace really cold.  Even in Michigan we have leaves on the trees at this point!  Seriously, nice job.', '2002-05-13 19:44:00.000000', NULL, 1),
