(60201, 1554, 1599, '<td valign="top">no</td>', 'no', '2002-05-13 17:59:00.000000', NULL, 1),
(60202, 1554, 1, '<td valign="top">Flash is overkill.</td>', 'Flash is overkill.', '2002-05-13 21:14:00.000000', NULL, 1),
(60203, 1554, 889, '<td valign="top">using more than the camera flash would be better or not using the internal flash if you can. Even if your laying on the floor with your legs up in the air.<br/>I think its differnt from any others though.</td>', 'using more than the camera flash would be better or not using the internal flash if you can. Even if your laying on the floor with your legs up in the air.I think its differnt from any others though.', '2002-05-14 00:43:00.000000', NULL, 1),
