(60212, 1554, 1476, '<td valign="top">very cool</td>', 'very cool', '2002-05-17 09:50:00.000000', NULL, 1),
(60213, 1554, 1078, '<td valign="top">Can''t say I want it framed and on my wall, but it''s fun anyway.  I think it would have been much better if you''d gone for a daytime shot instead of using the flash.  That would give you better lighting on the ceiling/chandelier and not overbrighten your pants and socks.</td>', 'Can''t say I want it framed and on my wall, but it''s fun anyway.  I think it would have been much better if you''d gone for a daytime shot instead of using the flash.  That would give you better lighting on the ceiling/chandelier and not overbrighten your pants and socks.', '2002-05-19 17:09:00.000000', NULL, 1),
(60214, 1555, 327, '<td valign="top">Cool perspective and a mighty nice shot!<br/>Well done.</td>', 'Cool perspective and a mighty nice shot!Well done.', '2002-05-13 16:12:00.000000', NULL, 1),
