(60223, 1555, 107, '<td valign="top">I like the colours in this one.</td>', 'I like the colours in this one.', '2002-05-15 07:16:00.000000', NULL, 1),
(60224, 1555, 1191, '<td valign="top">Lovely clarity, shame about the mesh background, it detracts slightly.</td>', 'Lovely clarity, shame about the mesh background, it detracts slightly.', '2002-05-17 17:25:00.000000', NULL, 1),
(60225, 1555, 875, '<td valign="top">Nice use of shape and color.  I like the way it feels like you are looking into an eye.</td>', 'Nice use of shape and color.  I like the way it feels like you are looking into an eye.', '2002-05-17 21:05:00.000000', NULL, 1),
(60226, 1555, 1078, '<td valign="top">I had to come back and look at this to figure out the orientation -- think I have it now.  I think I would have gone for a lightly tighter crop to remove the little bits in the lower corners that aren''t being seen from the inside of the glass.  Also, because I tend to like things like this not centered, I wonder if it would be possible to crops so the "stem" of the glass is further to the left -- but that might cause some other "outside the glass" difficulty -- not to mention being purely my own preference for composition.</td>', 'I had to come back and look at this to figure out the orientation -- think I have it now.  I think I would have gone for a lightly tighter crop to remove the little bits in the lower corners that aren''t being seen from the inside of the glass.  Also, because I tend to like things like this not centered, I wonder if it would be possible to crops so the "stem" of the glass is further to the left -- but that might cause some other "outside the glass" difficulty -- not to mention being purely my own preference for composition.', '2002-05-19 17:17:00.000000', NULL, 1),
(60227, 1555, 1379, '<td valign="top">Mmmm!</td>', 'Mmmm!', '2002-05-19 18:16:00.000000', NULL, 1),
