(60245, 1558, 1, '<td valign="top">Very nice shot -- the colors are great, the distortion on your face even better.</td>', 'Very nice shot -- the colors are great, the distortion on your face even better.', '2002-05-13 09:01:00.000000', NULL, 1),
(60246, 1558, 1175, '<td valign="top">this picture rocks.  I love the half blue half white. very nice and clean image.</td>', 'this picture rocks.  I love the half blue half white. very nice and clean image.', '2002-05-13 11:01:00.000000', NULL, 1),
