(60949, 1608, 1, '<td valign="top">Great symmetry, very well done.</td>', 'Great symmetry, very well done.', '2002-05-13 21:02:00.000000', NULL, 1),
(60950, 1608, 1528, '<td valign="top">Beautiful.<br/>I do wonder if this one would''nt be better upside right, though.  It would still convey ''upside down'' to me.</td>', 'Beautiful.I do wonder if this one would''nt be better upside right, though.  It would still convey ''upside down'' to me.', '2002-05-14 10:47:00.000000', NULL, 1),
(60951, 1608, 107, '<td valign="top">I like the way the photographer added an extra dimension by taking the picture (or rotating the picture) so it''s upside down.  It makes the viewer look twice to work out which is the reflection upon a seconds glance.  Really good job done, top marks.</td>', 'I like the way the photographer added an extra dimension by taking the picture (or rotating the picture) so it''s upside down.  It makes the viewer look twice to work out which is the reflection upon a seconds glance.  Really good job done, top marks.', '2002-05-14 16:10:00.000000', NULL, 1),
(60952, 1608, 1005, '<td valign="top">Good shot!  The whole thing is upside down.  I have really liked the shots where it was most difficult to tell which is which.  Great job! <br/>Photo 10 Creativity 10 Upsidedown 10  total 10 (you really nailed this one!)</td>', 'Good shot!  The whole thing is upside down.  I have really liked the shots where it was most difficult to tell which is which.  Great job! Photo 10 Creativity 10 Upsidedown 10  total 10 (you really nailed this one!)', '2002-05-14 19:01:00.000000', NULL, 1),
(60953, 1608, 878, '<td valign="top">Nice use of reflection to produce a symetrical shot.  I also like the fact that the reflection is on top</td>', 'Nice use of reflection to produce a symetrical shot.  I also like the fact that the reflection is on top', '2002-05-15 13:04:00.000000', NULL, 1),
(60954, 1608, 1191, '<td valign="top">Lovely image.</td>', 'Lovely image.', '2002-05-15 18:48:00.000000', NULL, 1),
