(61088, 1615, 1143, '<td valign="top">Beautiful shot. Not sure I''d be brave enough though.</td>', 'Beautiful shot. Not sure I''d be brave enough though.', '2002-05-13 23:15:00.000000', NULL, 1),
(61089, 1615, 543, '<td valign="top">Great tonal range.  I like the framing effect of the shadow and dark background,  and you seem to have posing well in hand {ahem}.  This should do very well, but I bet you get a lot more silly comments.  Applaud your bravery.  Using the highly scientific hold-your-hand-over-the-monitor technique, it looks like cropping right from the bottom of the angled shadow makes a nice vertical composition, as well.  My favorite (right after mine).</td>', 'Great tonal range.  I like the framing effect of the shadow and dark background,  and you seem to have posing well in hand {ahem}.  This should do very well, but I bet you get a lot more silly comments.  Applaud your bravery.  Using the highly scientific hold-your-hand-over-the-monitor technique, it looks like cropping right from the bottom of the angled shadow makes a nice vertical composition, as well.  My favorite (right after mine).', '2002-05-14 04:43:00.000000', NULL, 1),
(61090, 1615, 1024, '<td valign="top">This is one of the best executed upside down picture in this challenge.  I hope that voters can see the artistic value. Beautiful!  I especially like you use of light and shadow to bring the focus to the womans face.</td>', 'This is one of the best executed upside down picture in this challenge.  I hope that voters can see the artistic value. Beautiful!  I especially like you use of light and shadow to bring the focus to the womans face.', '2002-05-14 10:13:00.000000', NULL, 1),
(61091, 1615, 862, '<td valign="top">Excellent Lighting - nice and soft.  I love how she is framed by the light.  A frame within a frame.</td>', 'Excellent Lighting - nice and soft.  I love how she is framed by the light.  A frame within a frame.', '2002-05-14 10:19:00.000000', NULL, 1),
