(61243, 1621, 1154, '<td valign="top">Excellant!</td>', 'Excellant!', '2002-05-15 00:29:00.000000', NULL, 1),
(61244, 1621, 1360, '<td valign="top">I like the initial idea of this shot, but it''s missing something....</td>', 'I like the initial idea of this shot, but it''s missing something....', '2002-05-15 04:10:00.000000', NULL, 1),
(61245, 1621, 543, '<td valign="top">Nicely done.  I''d have gotten in a little closer to emphasize the glass over the surroundings, but that''s me.  Odd how the glass, wall, and buildings in the far background show more lean than the two dark buildings at UL.</td>', 'Nicely done.  I''d have gotten in a little closer to emphasize the glass over the surroundings, but that''s me.  Odd how the glass, wall, and buildings in the far background show more lean than the two dark buildings at UL.', '2002-05-15 04:22:00.000000', NULL, 1),
(61246, 1621, 107, '<td valign="top">fantastic shot. I love the way this is set up.</td>', 'fantastic shot. I love the way this is set up.', '2002-05-15 05:16:00.000000', NULL, 1),
(61247, 1621, 1024, '<td valign="top">This is very well done.  I think the spots on the glass are a little distracting though.</td>', 'This is very well done.  I think the spots on the glass are a little distracting though.', '2002-05-15 09:31:00.000000', NULL, 1),
(61248, 1621, 1570, '<td valign="top">this is nice, i liked the muted background and the way it reflects  in the glass...</td>', 'this is nice, i liked the muted background and the way it reflects  in the glass...', '2002-05-15 09:32:00.000000', NULL, 1),
(61249, 1621, 1078, '<td valign="top">GREAT idea.  I''d love to see this one shot again on a day with bright blue skies and puffy white clouds.  As it stands, though, the only comment I have is that I think I''d have tried to get rid of the air bubbles in the water, and the water spots on the upper part of the glass.  Make it a perfect "lens" without all the "imperfections".</td>', 'GREAT idea.  I''d love to see this one shot again on a day with bright blue skies and puffy white clouds.  As it stands, though, the only comment I have is that I think I''d have tried to get rid of the air bubbles in the water, and the water spots on the upper part of the glass.  Make it a perfect "lens" without all the "imperfections".', '2002-05-15 18:00:00.000000', NULL, 1),
(61250, 1621, 1233, '<td valign="top">Excellent.  Great presentation.</td>', 'Excellent.  Great presentation.', '2002-05-15 19:49:00.000000', NULL, 1),
(61251, 1621, 313, '<td valign="top">subtle.  nice composition.</td>', 'subtle.  nice composition.', '2002-05-15 23:48:00.000000', NULL, 1),
(61252, 1621, 1042, '<td valign="top">Very, very nice. I love this idea. It inspires me.</td>', 'Very, very nice. I love this idea. It inspires me.', '2002-05-16 01:56:00.000000', NULL, 1),
(61253, 1621, 1037, '<td valign="top">Very sneaky! It caught me by surprise. I love the distortion of the image in the glass.</td>', 'Very sneaky! It caught me by surprise. I love the distortion of the image in the glass.', '2002-05-16 02:22:00.000000', NULL, 1),
(61254, 1621, 1041, '<td valign="top">Very nicely composed and executed.  In my top 5.</td>', 'Very nicely composed and executed.  In my top 5.', '2002-05-16 08:55:00.000000', NULL, 1),
(61255, 1621, 2, '<td valign="top">This is an awesome effect -- though I think its two fallbacks are: 1 - the dirty glass.  2 - I think the title detracts from the effect of the photo, as it doesn''t match it well.</td>', 'This is an awesome effect -- though I think its two fallbacks are: 1 - the dirty glass.  2 - I think the title detracts from the effect of the photo, as it doesn''t match it well.', '2002-05-16 21:28:00.000000', NULL, 1),
