(61257, 1621, 675, '<td valign="top">you win, this shit rules...you are a golden god</td>', 'you win, this shit rules...you are a golden god', '2002-05-17 01:19:00.000000', NULL, 1),
(61258, 1621, 1066, '<td valign="top">Best of the water glass shots, and that is saying something since I contributed a water glass shot this week.<br/><br/>You have a better depth of field than any other and great idea of upside element.  One of my ten best.</td>', 'Best of the water glass shots, and that is saying something since I contributed a water glass shot this week.You have a better depth of field than any other and great idea of upside element.  One of my ten best.', '2002-05-17 13:31:00.000000', NULL, 1),
(61259, 1621, 1209, '<td valign="top">I really like this shot. It''s very well set up. But, the Atlanta paper tells me who it was taken by, if I''m not mistaken. So, I don''t feel comfortable scoring it higher than other favorites that remain anonymous.</td>', 'I really like this shot. It''s very well set up. But, the Atlanta paper tells me who it was taken by, if I''m not mistaken. So, I don''t feel comfortable scoring it higher than other favorites that remain anonymous.', '2002-05-17 17:39:00.000000', NULL, 1),
(61260, 1621, 811, '<td valign="top">Good capture and focus.  I like the fact that you have to look closely at the picture to see the "upside-down" part, yet it is obvious enough to not totally confound the viewer.  The paper and glasses give it a "natural" feel.</td>', 'Good capture and focus.  I like the fact that you have to look closely at the picture to see the "upside-down" part, yet it is obvious enough to not totally confound the viewer.  The paper and glasses give it a "natural" feel.', '2002-05-18 21:41:00.000000', NULL, 1),
(61261, 1621, 2, '<td valign="top">The details on this photo are hilarious.  Nice job, and congrats on the win!  :)</td>', 'The details on this photo are hilarious.  Nice job, and congrats on the win!  :)', '2002-05-20 01:09:00.000000', NULL, 0),
(61262, 1621, 244, '<td valign="top">Thanks for all of your comments and votes.  There were alot of things on this picture I wanted to do better but to be honest I didn''t have the time.  About the time I got it set up a police car showed up along with 2 officers and told me I couldn''t take pictures up there.  I told him I was almost done and he said 1 more shot, this was it.</td>', 'Thanks for all of your comments and votes.  There were alot of things on this picture I wanted to do better but to be honest I didn''t have the time.  About the time I got it set up a police car showed up along with 2 officers and told me I couldn''t take pictures up there.  I told him I was almost done and he said 1 more shot, this was it.', '2002-05-20 01:11:00.000000', NULL, 0),
(61263, 1621, 1485, '<td valign="top">Congrats!!  You deserve this one.. Super creativity with class!</td>', 'Congrats!!  You deserve this one.. Super creativity with class!', '2002-05-20 06:43:00.000000', NULL, 0),
(61264, 1621, 327, '<td valign="top">Very good. Well earned. CONGRATS. This is wonderful, I really enjoyed it.</td>', 'Very good. Well earned. CONGRATS. This is wonderful, I really enjoyed it.', '2002-05-20 10:36:00.000000', NULL, 0),
