(61363, 1627, 543, '<td valign="top">My favorite from grade school was 3704558.  Cool idea, but the techs need attention.</td>', 'My favorite from grade school was 3704558.  Cool idea, but the techs need attention.', '2002-05-13 23:40:00.000000', NULL, 1),
(61364, 1627, 1528, '<td valign="top">Love the subject matter- great idea!!!<br/>The green hues from the flourescent lights are no fun, I know how difficult they can be to overcome, though.  The thumb in front of his forehead moved a bit would be nice.  And I''m thinking the focus on the calculator, throwing the man out-of-focus might have been more appropriate?  <br/></td>', 'Love the subject matter- great idea!!!The green hues from the flourescent lights are no fun, I know how difficult they can be to overcome, though.  The thumb in front of his forehead moved a bit would be nice.  And I''m thinking the focus on the calculator, throwing the man out-of-focus might have been more appropriate?  ', '2002-05-14 01:15:00.000000', NULL, 1),
(61365, 1627, 885, '<td valign="top">You must be getting slammed on the white balance in the background, the fact that the flash overexposed the calculator, and the fact that the calculator isn''t in focus.</td>', 'You must be getting slammed on the white balance in the background, the fact that the flash overexposed the calculator, and the fact that the calculator isn''t in focus.', '2002-05-14 08:45:00.000000', NULL, 1),
