(61465, 1635, 142, '<td valign="top">In answer to one of my comments, yes it was taken during the challenge week.  The temperature was 93 degrees.  Summer begins much earlier here in the south.</td>', 'In answer to one of my comments, yes it was taken during the challenge week.  The temperature was 93 degrees.  Summer begins much earlier here in the south.', '2002-05-20 06:47:00.000000', NULL, 0),
(61466, 1639, 1485, '<td valign="top">icky picture but the out of focus softens the ick.  Looking aroud the ick, the compo is good.</td>', 'icky picture but the out of focus softens the ick.  Looking aroud the ick, the compo is good.', '2002-05-13 06:52:00.000000', NULL, 1),
(61467, 1639, 87, '<td valign="top">i gave a bug like this acid once.</td>', 'i gave a bug like this acid once.', '2002-05-13 07:12:00.000000', NULL, 1),
(61468, 1639, 327, '<td valign="top">Hee hee.....I saw him in Flordia. <br/>He looks better now. &amp;lt;g&amp;gt;<br/>Creative work, nice job.</td>', 'Hee hee.....I saw him in Flordia. He looks better now. &lt;g&gt;Creative work, nice job.', '2002-05-13 16:06:00.000000', NULL, 1),
(61469, 1639, 737, '<td valign="top">I would have liked everything in focus</td>', 'I would have liked everything in focus', '2002-05-13 13:11:00.000000', NULL, 1),
(61470, 1639, 772, '<td valign="top">This is a cool upside down bug.  A little more focus would possibly have provided a much cooler upside down bug!</td>', 'This is a cool upside down bug.  A little more focus would possibly have provided a much cooler upside down bug!', '2002-05-13 13:30:00.000000', NULL, 1),
(61471, 1639, 1600, '<td valign="top">out of focus</td>', 'out of focus', '2002-05-13 18:59:00.000000', NULL, 1),
(61472, 1639, 543, '<td valign="top">I wonder how this would look in B/W.  You might be able to pull out more detail in the head that way, or with a slight positive gamma adjustment.  Nice selective focus.  Chopping the antennae was your call, and I can''t really decide if I''d like it better with them included, so you get the benefit of the doubt.</td>', 'I wonder how this would look in B/W.  You might be able to pull out more detail in the head that way, or with a slight positive gamma adjustment.  Nice selective focus.  Chopping the antennae was your call, and I can''t really decide if I''d like it better with them included, so you get the benefit of the doubt.', '2002-05-14 04:38:00.000000', NULL, 1),
(61473, 1639, 1528, '<td valign="top">i like the composition<br/>don''t like the bug<br/>and focus looks good, right on his face<br/>but too dark, so it loses detail for me</td>', 'i like the compositiondon''t like the bugand focus looks good, right on his facebut too dark, so it loses detail for me', '2002-05-14 10:23:00.000000', NULL, 1),
(61474, 1639, 472, '<td valign="top">lordy lord but aint he the most disgusting critter you ever laid your eyes on?</td>', 'lordy lord but aint he the most disgusting critter you ever laid your eyes on?', '2002-05-14 10:24:00.000000', NULL, 1),
(61475, 1639, 1005, '<td valign="top">Macro shots are tricky, fuzzy legs.  Photo 7 Creative 6 Upsidedown 7 total 7</td>', 'Macro shots are tricky, fuzzy legs.  Photo 7 Creative 6 Upsidedown 7 total 7', '2002-05-14 14:17:00.000000', NULL, 1),
(61476, 1639, 1529, '<td valign="top">I suggest manual focus.</td>', 'I suggest manual focus.', '2002-05-14 20:10:00.000000', NULL, 1),
