(61683, 1650, 259, '<td valign="top">very cool, maybe done with a toy</td>', 'very cool, maybe done with a toy', '2002-05-16 00:34:00.000000', NULL, 1),
(61684, 1650, 1336, '<td valign="top">good lighting, nice perspective</td>', 'good lighting, nice perspective', '2002-05-16 10:56:00.000000', NULL, 1),
(61685, 1650, 1078, '<td valign="top">When I first saw this, I thought, "Wow, someone got lucky and found a flipped car after all!"  Nice little optical illusion. I think I would have tried to further that illusion by shooting it away from the grass that your flash managed to catch.  The trees and other things, if far enough in the background wouldn''t be an issue in terms of relative size.  I''d also like to see it in daylight specifically to play off those trees and that car in the background and some other things.  Maybe not possible, but I think it would be fun to try.  Good work.  :-)</td>', 'When I first saw this, I thought, "Wow, someone got lucky and found a flipped car after all!"  Nice little optical illusion. I think I would have tried to further that illusion by shooting it away from the grass that your flash managed to catch.  The trees and other things, if far enough in the background wouldn''t be an issue in terms of relative size.  I''d also like to see it in daylight specifically to play off those trees and that car in the background and some other things.  Maybe not possible, but I think it would be fun to try.  Good work.  :-)', '2002-05-16 16:08:00.000000', NULL, 1),
(61686, 1650, 675, '<td valign="top">haha, good job making it look authentic, it really worked nicely</td>', 'haha, good job making it look authentic, it really worked nicely', '2002-05-17 01:28:00.000000', NULL, 1),
(61687, 1650, 436, '<td valign="top">you had me for minute there.  only a second careful look showed the size of the grass blades in relation tothe car.  Well done!</td>', 'you had me for minute there.  only a second careful look showed the size of the grass blades in relation tothe car.  Well done!', '2002-05-17 08:27:00.000000', NULL, 1),
