INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(61843, 1662, 2, '<td valign="top">I''m pretty lost as to what''s going on here... but if it''s an hourglass, why are the edges faded?</td>', 'I''m pretty lost as to what''s going on here... but if it''s an hourglass, why are the edges faded?', '2002-05-16 23:07:00.000000', NULL, 1),
(61844, 1662, 875, '<td valign="top">Clever idea and a very nice effect.</td>', 'Clever idea and a very nice effect.', '2002-05-17 01:19:00.000000', NULL, 1),
(61845, 1662, 1078, '<td valign="top">While I have a couple of ideas about it, I''ll be interested to see how you did this (assuming you don''t really have an hour glass filled with coins).  It seems kind of dark -- either add a little bit of light to the shot, or make some adjustments in your image editing program.  Cool interpretation of the challenge.</td>', 'While I have a couple of ideas about it, I''ll be interested to see how you did this (assuming you don''t really have an hour glass filled with coins).  It seems kind of dark -- either add a little bit of light to the shot, or make some adjustments in your image editing program.  Cool interpretation of the challenge.', '2002-05-17 10:41:00.000000', NULL, 1),
(61846, 1662, 1446, '<td valign="top">Nice lighting, shadows and bringing my interest to the subject. Background works well with your shot. Overall Interpretation- The movement manages to add something, meets the challange.</td>', 'Nice lighting, shadows and bringing my interest to the subject. Background works well with your shot. Overall Interpretation- The movement manages to add something, meets the challange.', '2002-05-17 14:59:00.000000', NULL, 1),
(61847, 1662, 1191, '<td valign="top">Quite a neat image, well done.</td>', 'Quite a neat image, well done.', '2002-05-17 17:20:00.000000', NULL, 1),
(61848, 1662, 878, '<td valign="top">I like the blurred motion</td>', 'I like the blurred motion', '2002-05-17 18:54:00.000000', NULL, 1),
(61849, 1662, 1054, '<td valign="top">Well done, and a perfect candidate for a "how did you do that"</td>', 'Well done, and a perfect candidate for a "how did you do that"', '2002-05-18 08:44:00.000000', NULL, 1),
(61850, 1662, 811, '<td valign="top">Looks like they are falling up, which, I assume, was your purpose.  Good use of the motion trails versus the well-focused part.</td>', 'Looks like they are falling up, which, I assume, was your purpose.  Good use of the motion trails versus the well-focused part.', '2002-05-18 22:04:00.000000', NULL, 1),
(61851, 1662, 1128, '<td valign="top">Nice.  Can I have some?</td>', 'Nice.  Can I have some?', '2002-05-19 11:56:00.000000', NULL, 1),
(61852, 1662, 1379, '<td valign="top">Intense!</td>', 'Intense!', '2002-05-19 18:16:00.000000', NULL, 1),
(61853, 1664, 1485, '<td valign="top">nice composition.  Colors of pee wee''s chaor and the surrounding colors are nice.</td>', 'nice composition.  Colors of pee wee''s chaor and the surrounding colors are nice.', '2002-05-13 06:40:00.000000', NULL, 1),
(61854, 1664, 1037, '<td valign="top">I love this photo, it''s just so bizarre :) Great work.</td>', 'I love this photo, it''s just so bizarre :) Great work.', '2002-05-13 09:24:00.000000', NULL, 1),
(61855, 1664, 1175, '<td valign="top">I really like the bright and high saturated colors in this.  I also like how the two sides lead you into the corner with peewee on the sofa.  But, this challeng is a little more than just taking a good picture and turning it upside down.</td>', 'I really like the bright and high saturated colors in this.  I also like how the two sides lead you into the corner with peewee on the sofa.  But, this challeng is a little more than just taking a good picture and turning it upside down.', '2002-05-13 10:40:00.000000', NULL, 1),
(61856, 1664, 772, '<td valign="top">this one is twisting my neck :)</td>', 'this one is twisting my neck :)', '2002-05-13 14:18:00.000000', NULL, 1),
(61857, 1664, 327, '<td valign="top">&amp;lt;lol&amp;gt; Good humor and your on topic of the challenge.</td>', '&lt;lol&gt; Good humor and your on topic of the challenge.', '2002-05-13 16:58:00.000000', NULL, 1),
(61858, 1664, 472, '<td valign="top">majorly trippy : )</td>', 'majorly trippy : )', '2002-05-13 18:12:00.000000', NULL, 1),
(61859, 1664, 1599, '<td valign="top">so so........the challenge is upside down   RIGHT?</td>', 'so so........the challenge is upside down   RIGHT?', '2002-05-13 18:45:00.000000', NULL, 1),
(61860, 1664, 1457, '<td valign="top">is that pee-wee?</td>', 'is that pee-wee?', '2002-05-13 19:16:00.000000', NULL, 1),
(61861, 1664, 1, '<td valign="top">I could stand to see some more peewee action.  Is he waving to the cops?  The lighting is pretty sweet.</td>', 'I could stand to see some more peewee action.  Is he waving to the cops?  The lighting is pretty sweet.', '2002-05-13 20:38:00.000000', NULL, 1),
(61862, 1664, 543, '<td valign="top">Good, interesting stuff, but why upside down?  For the challenge?  Oh... I see.</td>', 'Good, interesting stuff, but why upside down?  For the challenge?  Oh... I see.', '2002-05-14 05:04:00.000000', NULL, 1),
(61863, 1664, 1005, '<td valign="top">Bizarre....Photo 8 Creativity 8 Upsidedown 7 total 8</td>', 'Bizarre....Photo 8 Creativity 8 Upsidedown 7 total 8', '2002-05-14 16:31:00.000000', NULL, 1),
(61864, 1664, 387, '<td valign="top">where''s his popcorn bucket with the hole in the bottom? Nice use of color and depth of field. oddly disturbing. . .</td>', 'where''s his popcorn bucket with the hole in the bottom? Nice use of color and depth of field. oddly disturbing. . .', '2002-05-14 18:16:00.000000', NULL, 1),
(61865, 1664, 878, '<td valign="top">Interesting</td>', 'Interesting', '2002-05-15 16:56:00.000000', NULL, 1),
(61866, 1664, 885, '<td valign="top">Interesting oversaturation.  I likt the green reflection.</td>', 'Interesting oversaturation.  I likt the green reflection.', '2002-05-16 08:04:00.000000', NULL, 1),
(61867, 1664, 47, '<td valign="top">PROPZ 4 HOMIE</td>', 'PROPZ 4 HOMIE', '2002-05-17 18:52:00.000000', NULL, 1),
(61868, 1664, 2, '<td valign="top">Very cool subject.  I love the bleeding colors in this shot as well as the way you''ve made the viewer uncomfortable in your use of ''upside-down''.  Very well done.</td>', 'Very cool subject.  I love the bleeding colors in this shot as well as the way you''ve made the viewer uncomfortable in your use of ''upside-down''.  Very well done.', '2002-05-19 21:27:00.000000', NULL, 1),
(61869, 1664, 48, '<td valign="top">its not dark enough for him to unzip and start his big adventure</td>', 'its not dark enough for him to unzip and start his big adventure', '2002-05-19 22:26:00.000000', NULL, 1),
(61870, 1664, 46, '<td valign="top">spose i should have made it more clear that i taped him to the top corner of my ceiling and took his pic from underneath.. ah well.</td>', 'spose i should have made it more clear that i taped him to the top corner of my ceiling and took his pic from underneath.. ah well.', '2002-05-20 02:09:00.000000', NULL, 0),
(61871, 1664, 47, '<td valign="top">yeah i was gonna say.. those colors are fucking hideous. good job.</td>', 'yeah i was gonna say.. those colors are fucking hideous. good job.', '2002-05-20 06:31:00.000000', NULL, 0),
(61872, 1665, 1024, '<td valign="top">gorgeous colors.</td>', 'gorgeous colors.', '2002-05-13 08:30:00.000000', NULL, 1),
(61873, 1665, 1175, '<td valign="top">There is more to this challenge then just taking a picture and turning it upside down.  If you are trying for a reflection you should have tried a different body of water or a better angle to make the reflection stand out.  Actually you may have even tried b&amp;w because the red raft sort of draws you into the middle and makes you miss the reflection.</td>', 'There is more to this challenge then just taking a picture and turning it upside down.  If you are trying for a reflection you should have tried a different body of water or a better angle to make the reflection stand out.  Actually you may have even tried b&w because the red raft sort of draws you into the middle and makes you miss the reflection.', '2002-05-13 10:45:00.000000', NULL, 1),
(61874, 1665, 327, '<td valign="top">Cute idea here. Great color too. Well done.</td>', 'Cute idea here. Great color too. Well done.', '2002-05-13 12:27:00.000000', NULL, 1),
(61875, 1665, 772, '<td valign="top">I really like the color contrast here between the float and the blue water :)</td>', 'I really like the color contrast here between the float and the blue water :)', '2002-05-13 14:09:00.000000', NULL, 1),
(61876, 1665, 472, '<td valign="top">killer colorz, dood. sony?  jumps right off the screen. too bad there''s grass around the pool instead of concrete though.</td>', 'killer colorz, dood. sony?  jumps right off the screen. too bad there''s grass around the pool instead of concrete though.', '2002-05-13 17:59:00.000000', NULL, 1),
(61877, 1665, 1599, '<td valign="top">WHERE ARE ALL THE SWIMMERS?</td>', 'WHERE ARE ALL THE SWIMMERS?', '2002-05-13 19:59:00.000000', NULL, 1),
(61878, 1665, 1005, '<td valign="top">Ooops...I see water.....Photo 9 Creative 5 Upsidedown 5 total 6</td>', 'Ooops...I see water.....Photo 9 Creative 5 Upsidedown 5 total 6', '2002-05-14 12:29:00.000000', NULL, 1),
(61879, 1665, 933, '<td valign="top">Not an especially engageing(sp?)  picture.  Maybe focusing more on one subject, like the raft, would create a more interesting image.</td>', 'Not an especially engageing(sp?)  picture.  Maybe focusing more on one subject, like the raft, would create a more interesting image.', '2002-05-14 14:11:00.000000', NULL, 1),
(61880, 1665, 656, '<td valign="top">think I would have liked this more without hte grass, and just the pool</td>', 'think I would have liked this more without hte grass, and just the pool', '2002-05-14 17:57:00.000000', NULL, 1),
(61881, 1665, 107, '<td valign="top">at least there''s a diving board to catch you if you fall out of the float....   I love the way the water was caught in this picture.</td>', 'at least there''s a diving board to catch you if you fall out of the float....   I love the way the water was caught in this picture.', '2002-05-15 09:09:00.000000', NULL, 1),
(61882, 1665, 1041, '<td valign="top">Very cool.  I feel all disoriented when I look at this.  In my top 5.</td>', 'Very cool.  I feel all disoriented when I look at this.  In my top 5.', '2002-05-16 08:54:00.000000', NULL, 1),
(61883, 1665, 901, '<td valign="top">i like it, it could of been better if their was a subject diving in the water.</td>', 'i like it, it could of been better if their was a subject diving in the water.', '2002-05-16 13:46:00.000000', NULL, 1),
(61884, 1665, 259, '<td valign="top">the blue in the photo is really impressive and i also like the contrast of the red against it.</td>', 'the blue in the photo is really impressive and i also like the contrast of the red against it.', '2002-05-16 23:45:00.000000', NULL, 1),
(61885, 1665, 875, '<td valign="top">Every time I look at this photo, I feel like I''m falling headfirst into the pool!  The raft adds some interest to the photo.</td>', 'Every time I look at this photo, I feel like I''m falling headfirst into the pool!  The raft adds some interest to the photo.', '2002-05-17 01:17:00.000000', NULL, 1),
(61886, 1665, 675, '<td valign="top">too simplistic</td>', 'too simplistic', '2002-05-17 01:37:00.000000', NULL, 1),
(61887, 1665, 1584, '<td valign="top">As the strangely reptilian diving board crouches, ,...the red ufo floats off in a cerulean sky.</td>', 'As the strangely reptilian diving board crouches, ,...the red ufo floats off in a cerulean sky.', '2002-05-18 21:22:00.000000', NULL, 1),
(61888, 1665, 1, '<td valign="top">Bland subject: just a snapshot turned upside down.</td>', 'Bland subject: just a snapshot turned upside down.', '2002-05-19 22:34:00.000000', NULL, 1),
(61889, 1666, 1485, '<td valign="top">creative thinking</td>', 'creative thinking', '2002-05-13 06:58:00.000000', NULL, 1),
(61890, 1666, 1, '<td valign="top">Nothing is upside down in the picture without your title to help it.  Otherwise it''s a great shot.</td>', 'Nothing is upside down in the picture without your title to help it.  Otherwise it''s a great shot.', '2002-05-13 08:53:00.000000', NULL, 1),
(61891, 1666, 1379, '<td valign="top">Cool!</td>', 'Cool!', '2002-05-13 09:05:00.000000', NULL, 1),
(61892, 1666, 327, '<td valign="top">Ha! clever idea and nice work.<br/></td>', 'Ha! clever idea and nice work.', '2002-05-13 12:11:00.000000', NULL, 1),
(61893, 1666, 472, '<td valign="top">should have flipped image 180 deg.  kuddos for excellent lighting and quality, though</td>', 'should have flipped image 180 deg.  kuddos for excellent lighting and quality, though', '2002-05-13 18:09:00.000000', NULL, 1),
(61894, 1666, 772, '<td valign="top">I like the colors and lighting on this shot quite a bit.. they are impressive!  Is this glass upside down and is the water being shot up into it?   The glass appears to be mostly level but the angle of the dark line base is a little off... none-the-less, a very nice photo!</td>', 'I like the colors and lighting on this shot quite a bit.. they are impressive!  Is this glass upside down and is the water being shot up into it?   The glass appears to be mostly level but the angle of the dark line base is a little off... none-the-less, a very nice photo!', '2002-05-13 18:10:00.000000', NULL, 1),
(61895, 1666, 1457, '<td valign="top">nice capture</td>', 'nice capture', '2002-05-13 19:10:00.000000', NULL, 1),
(61896, 1666, 1599, '<td valign="top">DIFFERENT. BUT I THINK IT WAS USED BEFORE</td>', 'DIFFERENT. BUT I THINK IT WAS USED BEFORE', '2002-05-13 20:07:00.000000', NULL, 1),
(61897, 1666, 1528, '<td valign="top">I like it!<br/>What about if it was upside down though?<br/>Lighting is great.</td>', 'I like it!What about if it was upside down though?Lighting is great.', '2002-05-13 23:21:00.000000', NULL, 1),
(61898, 1666, 543, '<td valign="top">Hot glue gun and a water pistol?  A very creative approach, whatever it was.  Only nit is the focus seems to be slightly ahead of the glass (the front of the base looks sharp, as does the droplet at center L), and the reflections could have been tamed a little better.  Well done.</td>', 'Hot glue gun and a water pistol?  A very creative approach, whatever it was.  Only nit is the focus seems to be slightly ahead of the glass (the front of the base looks sharp, as does the droplet at center L), and the reflections could have been tamed a little better.  Well done.', '2002-05-14 04:49:00.000000', NULL, 1),
(61899, 1666, 1005, '<td valign="top">Clever!  Wouldn''t change a thing!  Great job!  Photo 10 Creativity 10 Upsidedown 10 total 10   (you really nailed this one!)</td>', 'Clever!  Wouldn''t change a thing!  Great job!  Photo 10 Creativity 10 Upsidedown 10 total 10   (you really nailed this one!)', '2002-05-14 18:26:00.000000', NULL, 1),
(61900, 1666, 675, '<td valign="top">i don''t get it, but whatever, i don''t get much, the actual picture is very good quality, maybe some explanation on this would help</td>', 'i don''t get it, but whatever, i don''t get much, the actual picture is very good quality, maybe some explanation on this would help', '2002-05-14 21:13:00.000000', NULL, 1),
(61901, 1666, 878, '<td valign="top">Interesting photo</td>', 'Interesting photo', '2002-05-15 12:54:00.000000', NULL, 1),
(61902, 1666, 1135, '<td valign="top">Nice lighting and color. In my top 5!</td>', 'Nice lighting and color. In my top 5!', '2002-05-16 01:31:00.000000', NULL, 1),
(61903, 1666, 885, '<td valign="top">Nice lighting and background.  "horizon" line seems a little tilted though.  I think if this were flipped over 180 degrees, it would be more obvious while still fitting the upside down subject part of the challenge.</td>', 'Nice lighting and background.  "horizon" line seems a little tilted though.  I think if this were flipped over 180 degrees, it would be more obvious while still fitting the upside down subject part of the challenge.', '2002-05-16 08:03:00.000000', NULL, 1),
(61904, 1666, 1041, '<td valign="top">Nicely done!  The background does not seem to be totally level, or is that just because of the way the lighting is.  I know the rules don''t allow this, but for outside of the competition, I would try and crop the sides tighter and show more of the water at the top.</td>', 'Nicely done!  The background does not seem to be totally level, or is that just because of the way the lighting is.  I know the rules don''t allow this, but for outside of the competition, I would try and crop the sides tighter and show more of the water at the top.', '2002-05-16 08:59:00.000000', NULL, 1),
(61905, 1666, 107, '<td valign="top">I love this shot.</td>', 'I love this shot.', '2002-05-16 10:17:00.000000', NULL, 1),
(61906, 1666, 1078, '<td valign="top">What''s upside down about this?  You''re just pouring water and it''s splashing out, right?  (Just kidding... I DO see it.)  This is one that I think has a little bit too shallow a depth of field.  The shutter speed looks like it was fast enough to freeze the water, but a lot of the water is unfocused.  The lighting is also a little unbalanced -- I can see the background on the right, not on the left, and I can see a sharp delineation between base and background.  I think I''d like to see a little more of that blue on the left -- maybe another light source to help bring that out of the shadow?</td>', 'What''s upside down about this?  You''re just pouring water and it''s splashing out, right?  (Just kidding... I DO see it.)  This is one that I think has a little bit too shallow a depth of field.  The shutter speed looks like it was fast enough to freeze the water, but a lot of the water is unfocused.  The lighting is also a little unbalanced -- I can see the background on the right, not on the left, and I can see a sharp delineation between base and background.  I think I''d like to see a little more of that blue on the left -- maybe another light source to help bring that out of the shadow?', '2002-05-16 15:52:00.000000', NULL, 1),
(61907, 1666, 875, '<td valign="top">I love the blue background and the nice focus.</td>', 'I love the blue background and the nice focus.', '2002-05-17 01:16:00.000000', NULL, 1),
(61908, 1666, 889, '<td valign="top">That would have been a great stop action shot, but then again what would you have done for this one?<br/>great idea with a new twidt</td>', 'That would have been a great stop action shot, but then again what would you have done for this one?great idea with a new twidt', '2002-05-17 12:23:00.000000', NULL, 1),
(61909, 1666, 811, '<td valign="top">Yea!! More stopped water shots!  Just kidding.  It''s a little bright on the right side -- maybe use some fill light on the left.  What would have been truly effective (but I don''t know if it would be possible or not) is if the reflection in the glass had been very obvious.</td>', 'Yea!! More stopped water shots!  Just kidding.  It''s a little bright on the right side -- maybe use some fill light on the left.  What would have been truly effective (but I don''t know if it would be possible or not) is if the reflection in the glass had been very obvious.', '2002-05-18 22:02:00.000000', NULL, 1),
(61910, 1666, 1344, '<td valign="top">The photo was taken with the glass hanging upside down with water shooting up into it...  Flipped it 180 degrees to try for the effect of having the water coming straight up out of the glass -- guess I didn''t choose the right shot to fully show that effect.  Probably would have done better if I just kept the image facing down as most people probably didn''t understand what I was going for..  Will put up some setup shots in the forum if anyone''s interested.  Thanks for all the nice comments -- I like how this pic came out!</td>', 'The photo was taken with the glass hanging upside down with water shooting up into it...  Flipped it 180 degrees to try for the effect of having the water coming straight up out of the glass -- guess I didn''t choose the right shot to fully show that effect.  Probably would have done better if I just kept the image facing down as most people probably didn''t understand what I was going for..  Will put up some setup shots in the forum if anyone''s interested.  Thanks for all the nice comments -- I like how this pic came out!', '2002-05-20 10:06:00.000000', NULL, 0),
(61911, 1667, 1379, '<td valign="top">North America DOES feel upside down at times...</td>', 'North America DOES feel upside down at times...', '2002-05-13 05:37:00.000000', NULL, 1),
(61912, 1667, 327, '<td valign="top">Wow. Good idea. On the subject!<br/>I think the angle could of been improved. Glare, flash on the right side.<br/>Interesting place, what is it?</td>', 'Wow. Good idea. On the subject!I think the angle could of been improved. Glare, flash on the right side.Interesting place, what is it?', '2002-05-13 12:10:00.000000', NULL, 1),
(61913, 1667, 772, '<td valign="top">This is a nice shot!  I would really like to see the globe centered up between the two columns to add some nice symmetry to this photo... good job!</td>', 'This is a nice shot!  I would really like to see the globe centered up between the two columns to add some nice symmetry to this photo... good job!', '2002-05-13 17:39:00.000000', NULL, 1),
(61914, 1667, 1599, '<td valign="top">very good</td>', 'very good', '2002-05-13 17:48:00.000000', NULL, 1),
(61915, 1667, 1457, '<td valign="top">the have somrthing like this at the summerst collection by my house</td>', 'the have somrthing like this at the summerst collection by my house', '2002-05-13 19:04:00.000000', NULL, 1),
(61916, 1667, 554, '<td valign="top">This is perfect (except for slight mis alignment on base)   10</td>', 'This is perfect (except for slight mis alignment on base)   10', '2002-05-13 21:04:00.000000', NULL, 1),
(61917, 1667, 509, '<td valign="top">I like this, but would have voted much higher if the globe was centerred between those two pillars, that would have also eliminated the bush on the right</td>', 'I like this, but would have voted much higher if the globe was centerred between those two pillars, that would have also eliminated the bush on the right', '2002-05-13 23:24:00.000000', NULL, 1),
(61918, 1667, 1037, '<td valign="top">Very nice globe... but it''s a shame that the background couldn''t be more aesthetically pleasing to go with it. I love those reflections.</td>', 'Very nice globe... but it''s a shame that the background couldn''t be more aesthetically pleasing to go with it. I love those reflections.', '2002-05-13 23:44:00.000000', NULL, 1),
(61919, 1667, 472, '<td valign="top">that is a cool sculpture!  shoulda got closer and filled the frame with the ball IMO</td>', 'that is a cool sculpture!  shoulda got closer and filled the frame with the ball IMO', '2002-05-14 21:21:00.000000', NULL, 1),
(61920, 1667, 1005, '<td valign="top">Pretty (big) marble!  I wonder what could have been done about the glare off the marble?  Did you try a lower camera angle? Flash?  <br/>Photo 9 Creativity 7 Upsidedown 8 total 8</td>', 'Pretty (big) marble!  I wonder what could have been done about the glare off the marble?  Did you try a lower camera angle? Flash?  Photo 9 Creativity 7 Upsidedown 8 total 8', '2002-05-15 12:53:00.000000', NULL, 1),
(61921, 1667, 878, '<td valign="top">Well I know what your doing with this shot, I think the angle of it was a bit off.  The granite(?) collums in the back ground are not lined up with the subject and there is a bit of overexposure caused from the flash on the base of the platform.  I think if you took a few more shots of the this you could of gotten a better result when you got the right angle.</td>', 'Well I know what your doing with this shot, I think the angle of it was a bit off.  The granite(?) collums in the back ground are not lined up with the subject and there is a bit of overexposure caused from the flash on the base of the platform.  I think if you took a few more shots of the this you could of gotten a better result when you got the right angle.', '2002-05-15 13:22:00.000000', NULL, 1),
(61922, 1667, 675, '<td valign="top">yeah yeah, nice try, how come you didn''t try to get it centered?</td>', 'yeah yeah, nice try, how come you didn''t try to get it centered?', '2002-05-17 01:31:00.000000', NULL, 1),
(61923, 1667, 889, '<td valign="top">I cant wait to see where people play with the large marbles.</td>', 'I cant wait to see where people play with the large marbles.', '2002-05-17 12:06:00.000000', NULL, 1),
(61924, 1667, 1540, '<td valign="top">This would have been much better if you had centered the globe between the pillars. But a nice shot anyway.</td>', 'This would have been much better if you had centered the globe between the pillars. But a nice shot anyway.', '2002-05-17 16:05:00.000000', NULL, 1),
(61925, 1667, 1070, '<td valign="top">looks odd not beeing symetrical</td>', 'looks odd not beeing symetrical', '2002-05-18 08:16:00.000000', NULL, 1),
